import { isMotionValue, motionValue } from "framer-motion/dom";
import { attachFollow } from "motion-dom";
import { watch, extract } from "../vendor/runed/index.js";
export function useFollowValue(source, options = {}) {
    const value = motionValue(isMotionValue(source) ? source.get() : source);
    watch(() => extract(options), (currentOptions) => attachFollow(value, source, currentOptions));
    return value;
}
export function useSpring(source, config = {}) {
    return useFollowValue(source, () => ({ type: "spring", ...extract(config) }));
}
